    var a = 0
    while a < 7 {
        var b = a + 1
        while b < 7 {
            var us = 0 - 1
            while us <= 1 {
                if us != 0 {
                    // second primitive (c<d in S) x sign
                    var cc = 0
                    while cc < 7 {
                        var dd = cc + 1
                        while dd < 7 {
                            var vs = 0 - 1
                            while vs <= 1 {
                                if vs != 0 {
